#include <pybind11/complex.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/robotweax_srt/srt_source.h>
// pydoc.h is automatically generated in the build directory
#include <srt_source_pydoc.h>

void bind_srt_source(py::module& m)
{
    using srt_source = gr::robotweax_srt::srt_source;

    py::class_<srt_source, gr::sync_block, gr::block, gr::basic_block, std::shared_ptr<srt_source>>(
        m, "srt_source", D(srt_source))
        .def(py::init(&srt_source::make), py::arg("transport"), py::arg("stream"), D(srt_source, make))
        .def("status_json", &srt_source::status_json)
        .def("status_pmt", &srt_source::status_pmt)
        // Dictionary form of the status snapshot.
        .def("status", [](const srt_source& self) {
            return py::module::import("json").attr("loads")(self.status_json());
        });
}
